defmodule Ash.Resource.ManualRead do
  @moduledoc """
  A module to implement manual read actions.
  """

  @type context :: %{
          optional(:actor) => term,
          optional(:tenant) => term,
          optional(:authorize?) => boolean,
          optional(:domain) => module,
          optional(any) => any
        }

  @type extra_info :: %{
          optional(:full_count) => non_neg_integer()
        }

  @callback load_relationships(
              query :: Ash.Query.t(),
              results :: list(Ash.Resource.Record.t()),
              opts :: Keyword.t(),
              context :: context(),
              lazy? :: boolean()
            ) ::
              {:ok, list(Ash.Resource.Record.t())}
              | {:ok, list(Ash.Resource.Record.t()), extra_info()}
              | {:error, term}

  @callback read(
              query :: Ash.Query.t(),
              data_layer_query :: term,
              opts :: Keyword.t(),
              context :: context()
            ) ::
              {:ok, list(Ash.Resource.Record.t())}
              | {:ok, list(Ash.Resource.Record.t()), extra_info()}
              | {:error, term}

  @optional_callbacks [
    load_relationships: 5
  ]

  @doc false
  @spec read(module(), Ash.Query.t(), term(), Keyword.t(), context()) ::
          {:ok, list(Ash.Resource.Record.t())}
          | {:ok, list(Ash.Resource.Record.t()), extra_info()}
          | {:error, term()}
  def read(module, query, data_layer_query, opts, context) do
    Ash.BehaviourHelpers.call_and_validate_return(
      module,
      :read,
      [query, data_layer_query, opts, context],
      [{:ok, :_}, {:ok, :_, :_}, {:error, :_}],
      behaviour: __MODULE__,
      callback_name: "read/4"
    )
  end

  @doc false
  @spec load_relationships(
          module(),
          Ash.Query.t(),
          list(Ash.Resource.Record.t()),
          Keyword.t(),
          context(),
          boolean()
        ) ::
          {:ok, list(Ash.Resource.Record.t())}
          | {:ok, list(Ash.Resource.Record.t()), extra_info()}
          | {:error, term()}
  def load_relationships(module, query, results, opts, context, lazy?) do
    Ash.BehaviourHelpers.call_and_validate_return(
      module,
      :load_relationships,
      [query, results, opts, context, lazy?],
      [{:ok, :_}, {:ok, :_, :_}, {:error, :_}],
      behaviour: __MODULE__,
      callback_name: "load_relationships/5"
    )
  end

  defmacro __using__(_) do
    quote do
      @behaviour Ash.Resource.ManualRead
      @before_compile Ash.Resource.ManualRead
    end
  end

  defmacro __before_compile__(_) do
    quote do
      if Module.defines?(__MODULE__, {:load_relationships, 5}, :def) do
        def has_load_relationships?, do: true
      else
        def has_load_relationships?, do: false
      end
    end
  end
end

@spec set_metadata(Ash.Resource.Record.t(), map) :: Ash.Resource.Record.t()
def set_metadata(record, map) do
  %{record | __metadata__: Ash.Helpers.deep_merge_maps(record.__metadata__, map)}
end

@doc false
def set_meta(%{__meta__: _} = struct, meta) do
  %{struct | __meta__: meta}
end

def set_meta(struct, _), do: struct

@spec put_metadata(Ash.Resource.Record.t(), atom, term) :: Ash.Resource.Record.t()
def put_metadata(record, key, term) do
  set_metadata(record, %{key => term})
end

@doc "Sets a list of loaded key or paths to a key back to their original unloaded stated"
@spec unload_many(
        nil | list(Ash.Resource.Record.t()) | Ash.Resource.Record.t() | Ash.Page.page(),
        list(atom) | list(list(atom))
      ) ::
        nil | list(Ash.Resource.Record.t()) | Ash.Resource.Record.t() | Ash.Page.page()
def unload_many(data, paths) do
  Enum.reduce(paths, data, &unload(&2, &1))
end

@doc "Sets a loaded key or path to a key back to its original unloaded stated"
@spec unload(
        nil | list(Ash.Resource.Record.t()) | Ash.Resource.Record.t() | Ash.Page.page(),
        atom | list(atom)
      ) ::
        nil | list(Ash.Resource.Record.t()) | Ash.Resource.Record.t() | Ash.Page.page()
def unload(nil, _), do: nil

def unload(%struct{results: results} = page, path)

